        swMeasurements = phantomResult.sw;

        // ===================================================================
        // MERGE DATA AND COMPUTE DELTAS
        // ===================================================================

        var formatConfig = {
            "tableUnits" : definition.tableUnits,
            "sigFigs" : definition.sigFigs,
            "showUnits" : definition.showUnits,
            "detailLevel" : definition.detailLevel,
            "language" : definition.language
        } as FormatConfig;

        // Station numbering: DEFAULT numbers from the min-X station; CUSTOM
        // numbers outward from the station nearest a chosen reference.
        var stationNumbering = {
            "mode" : definition.stationNumbering,
            "direction" : STATION_DIRECTION.INCREASE_WITH_X,
            "station0X" : 0 * millimeter
        };
        if (definition.stationNumbering == STATION_NUMBERING.CUSTOM)
        {
            stationNumbering.station0X = extractXPosition(context, definition.station0Ref, "Station 0 Reference");
            stationNumbering.direction = definition.stationDirection;
        }

        var tableData = mergeStationData(
            stations,
            coreMeasurements,
            swMeasurements,
            boundaries,
            coreExtents,
            swExtents,
            tableOriginX,
            swFromEndX,
            formatConfig,
            stationNumbering
        );

        // Sort by table order
        tableData = sortTableRows(tableData, definition.tableOrder, boundaries);

        if (definition.verbose)
        {
            println("Table rows: " ~ size(tableData));
        }

        // ===================================================================
        // STORE AS ATTRIBUTE
        // ===================================================================

        setAttribute(context, {
            "entities" : qOrigin(EntityType.BODY),
            "name" : "qcTableData",
            "attribute" : {
                "data" : tableData,
                "hasCore" : hasCore,
                "hasSW" : hasSW,
                "hasSwFromEnd" : (swFromEndX != undefined),
                "detailLevel" : definition.detailLevel,
                "format" : formatConfig,
                "tableName" : definition.tableName
            }
        });

        if (definition.verbose)
        {
            println("QC Table generation complete");
        }
    });

// ============================================================================
// TABLE DEFINITION
// ============================================================================

annotation { "Table Type Name" : "QC Table", "Icon" : IconNamespace::BLOB_DATA }
export const qcTable = defineTable(function(context is Context, definition is map) returns Table
    precondition
    {
        // No additional parameters needed
    }
    {
        // Find bodies with qcTableData attribute
        var bodiesWithAttribute = evaluateQuery(context, qHasAttribute("qcTableData"));

        if (size(bodiesWithAttribute) == 0)
        {
            // No data - return empty table
            return table("QC Table (No Data)", [], []);
        }

        // Get attribute data
        var tableAttribute = getAttribute(context, {
            "entity" : bodiesWithAttribute[0],
            "name" : "qcTableData"
        });

        var tableData = tableAttribute.data;
        var hasCore = tableAttribute.hasCore;
        var hasSW = tableAttribute.hasSW;
        var detailLevel = tableAttribute.detailLevel;
        var formatConfig = tableAttribute.format;
        var language = (formatConfig.language != undefined) ? formatConfig.language : LANGUAGE.ENG;
        var hasSwFromEnd = (tableAttribute.hasSwFromEnd != undefined) ? tableAttribute.hasSwFromEnd : false;

        // Build dynamic column definitions
        var columns = buildColumnDefinitions(hasCore, hasSW, detailLevel, language, hasSwFromEnd);

        // Build table rows
        var rows = [];
        for (var rowData in tableData)
        {
            rows = append(rows, tableRow(rowData));
        }

        // Return table with appropriate title. A user-supplied Name overrides
        // the auto-generated title; older attributes may lack the field.
        var tableName = (tableAttribute.tableName != undefined) ? tableAttribute.tableName : "";

        var title = "QC Table";
        if (tableName != "")
        {
            title = tableName;
        }
        else if (hasCore && hasSW)
        {
            title = "QC Table (Core + Sidewall)";
        }
        else if (hasCore)
        {
            title = "QC Table (Core Only)";
        }
        else if (hasSW)
        {
            title = "QC Table (Sidewall Only)";
        }

        return table(title, columns, rows);
    });

